// ── Verify-prep + message builder for "booking.confirmed" events sent by the portfolio site ──
// The HMAC itself is computed by the next (Crypto) node; this node checks freshness/shape and builds
// the exact string that was signed: `${timestamp}.${rawBody}`. (JSON.stringify(parsed body) is
// byte-identical to the compact JSON the site sent.)
const input = $input.first().json;
const headers = input.headers || {};
const body = input.body || {};
const fail = (reason) => [{ json: { ok: false, reason } }];

const secret = String($env.BOOKING_WEBHOOK_SECRET || '');
if (secret.length < 16) return fail('not_configured');

const ts = String(headers['x-booking-timestamp'] || '');
const receivedSig = String(headers['x-booking-signature'] || '');
const tsMs = Number(ts);
if (!Number.isFinite(tsMs) || Math.abs(Date.now() - tsMs) > 5 * 60 * 1000) return fail('stale_or_missing_timestamp');
if (!/^sha256=[0-9a-f]{64}$/.test(receivedSig)) return fail('bad_signature_format');

const b = body.booking || {};
if (body.event !== 'booking.confirmed' || !/^\+91[6-9]\d{9}$/.test(String(b.phone || '')) || !b.ref || !b.paymentId) {
  return fail('bad_payload');
}

const inr = (n) => '₹' + Number(n || 0).toLocaleString('en-IN');
const line = (s, max) => String(s || '').replace(/[\u0000-\u001f\u007f]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max);
const yourName = $env.YOUR_NAME || 'Nikhil';
const name = line(b.name, 60);
const company = line(b.company, 60);
const service = line(b.service, 80);
const first = name.split(' ')[0] || 'there';

const text = [
  `Hi ${first}, this is ${yourName}'s booking assistant 🤖`,
  '',
  `Your booking for *${service}*${company ? ` (${company})` : ''} is confirmed ✅ (Ref: ${b.ref})`,
  '',
  `*Project total:* ${inr(b.total)}`,
  `• Paid now (${b.tokenPercent}%): ${inr(b.token)} ✅`,
  `• At project start (${b.startPercent}%): ${inr(b.startAdvance)}`,
  `• After completion (${b.remainingPercent}%): ${inr(b.remaining)}`,
  ...(b.startDate ? ['', `Preferred start date: ${line(b.startDate, 10)}`] : []),
  '',
  `${yourName} will personally contact you soon to go through your requirements. You can reply here with any questions in the meantime.`
].join('\n');

// Single-line, structured facts only. This goes into the AI's "Notes" — never free text from the client.
const notes = `Booking ${b.ref}: ${service}, total ${inr(b.total)}; token ${inr(b.token)} paid; ${inr(b.startAdvance)} due at project start; ${inr(b.remaining)} due after completion.${b.startDate ? ` Preferred start ${line(b.startDate, 10)}.` : ''}`;

return [{
  json: {
    ok: true,
    signedString: `${ts}.${JSON.stringify(body)}`,
    receivedSig,
    phone: b.phone,
    name,
    ref: b.ref,
    paymentId: String(b.paymentId),
    resend: body.resend === true,
    text,
    notes,
    instanceName: $env.EVOLUTION_INSTANCE_NAME || 'default'
  }
}];

